<script setup>
import { computed, ref } from "vue";const props=defineProps({title:String,steps:Array,analogy:String});const active=ref(0);const step=computed(()=>props.steps[active.value]);
</script>
<template><section class="flow-walkthrough"><header><span>DATA-FLOW WALKTHROUGH</span><h3>{{title}}</h3><p v-if="analogy">{{analogy}}</p></header><div class="flow-rail" role="tablist"><button v-for="(item,i) in steps" :key="i" role="tab" :aria-selected="active===i" :class="{active:active===i,done:i<active}" @click="active=i"><b>{{String(i+1).padStart(2,'0')}}</b><span>{{item.actor}}</span></button></div><article class="flow-detail" role="tabpanel"><div><span>WHO ACTS</span><strong>{{step.actor}}</strong></div><div><span>DATA IN</span><code>{{step.input}}</code></div><div><span>WHAT HAPPENS</span><p>{{step.action}}</p></div><div><span>DATA OUT</span><code>{{step.output}}</code></div><div v-if="step.analogy" class="flow-analogy"><span>SPORTS BROADCAST ANALOGY</span><p>{{step.analogy}}</p></div></article></section></template>
